import { Injectable } from '@angular/core';
import { ethers } from 'ethers';
import { BlockchainConfigService } from './blockchain-config.service';
import { ToastService } from './toast.service';
import { ContractService } from './contract.service';
import { Subscription, combineLatest, firstValueFrom, filter } from 'rxjs';
import { TransactionInterceptorService } from './transaction-interceptor.service';
import * as Abis from '@core/abis';
import { LoggerService } from "@services/logger.service";

/**
 * Deployment metadata stored in registry
 */
export interface LockerMetadata {
    name: string;
    description: string;
    website?: string;
    contact?: string;
}

/**
 * Deployment record from registry
 */
export interface Deployment {
    id: number;
    lockerAddress: string;
    owner: string;
    deployedAt: number;
    paidAmount: bigint;
    metadata: LockerMetadata;
}

/**
 * Interface for tracking deployment process steps
 */
export interface DeploymentStep {
    id: string;
    name: string;
    status: 'pending' | 'deploying' | 'completed' | 'error';
    address?: string;
    errorMessage?: string;
}

/**
 * Pricing tier information
 */
export interface PricingInfo {
    currentPrice: number; // In USD
    isEarlyBird: boolean;
    remainingEarlyBird: number;
    totalDeployments: number;
    earlyBirdLimit: number;
    regularPrice: number;
}

const DEPLOYMENT_REGISTRY_ABI = [
    // Read
    'function getCurrentPrice() view returns (uint256)',
    'function getRemainingEarlyBird() view returns (uint256)',
    'function totalDeployments() view returns (uint256)',
    'function EARLY_BIRD_LIMIT() view returns (uint256)',
    'function EARLY_BIRD_PRICE() view returns (uint256)',
    'function REGULAR_PRICE() view returns (uint256)',
    'function canUserDeploy(address user) view returns (bool)',
    'function hasUserDeployed(address user) view returns (bool)',
    'function acceptedTokens(address token) view returns (bool)',
    'function getBytecode(string contractName) view returns (bytes)',
    'function canDeploy(address) view returns (bool)',
    'function getDeploymentProgress(address deployer) view returns (tuple(address priceCalculator, address validationHandler, address lockManager, address signerManager, address vestingManager, address lockerContract, bool finalized))',
    // Write
    'function payForDeployment(address tokenAddress) external',
    'function registerDeployedContract(string calldata contractName, address contractAddress) external',
    // Admin (Write)
    'function grantDeployments(address[] calldata deployers) external',
    'function revokeDeployments(address[] calldata deployers) external',
    'function addAcceptedTokenWithLockId(address tokenAddress, uint256 _lockId) external',
    'function setTokenLockId(address tokenAddress, uint256 _lockId) external',
    'function storeBytecode(string memory contractName, bytes memory bytecode) external',
    // Events
    'event PaymentReceived(address indexed deployer, address indexed token, uint256 amount, uint256 lockId)',
    'event DeploymentGranted(address indexed deployer)',
    'event DeploymentStepRegistered(address indexed deployer, string contractName, address contractAddress)',
    'event DeploymentCompleted(address indexed deployer, address lockerContract)'
];

/**
 * Service to interact with DeploymentRegistry contract
 */
@Injectable({
    providedIn: 'root'
})
export class DeploymentRegistryService {
    private provider: ethers.Provider | null = null;
    private signer: ethers.Signer | null = null;
    private currentChainId: number | null = null;
    private readonly subs = new Subscription();

    constructor(
        private blockchainConfig: BlockchainConfigService,
        private toastService: ToastService,
        private contractService: ContractService,
        private txInterceptor: TransactionInterceptorService, private logger: LoggerService
    ) {
        this.subs.add(
            combineLatest([
                this.contractService.chainId$,
                this.contractService.account$
            ]).subscribe(([chainId]) => {
                if (chainId) {
                    this.init(
                        this.contractService.getProvider()!,
                        this.contractService.getSigner(),
                        Number(chainId)
                    );
                }
            })
        );
    }

    ngOnDestroy() {
        this.subs.unsubscribe();
    }

    /**
     * Ensure the service is initialized with chainId and config
     */
    private async ensureReady(): Promise<void> {
        if (!this.currentChainId) {
            const chainId = await firstValueFrom(
                this.contractService.chainId$.pipe(filter(id => id !== null))
            );
            this.currentChainId = Number(chainId);
            this.provider = this.contractService.getProvider()!;
            this.signer = this.contractService.getSigner();
        }
        await this.blockchainConfig.loadConfig();
    }

    /**
     * Initialize with provider and signer
     */
    async init(provider: ethers.Provider, signer: ethers.Signer | null, chainId: number) {
        this.provider = provider;
        this.signer = signer;
        this.currentChainId = chainId;

        // Load blockchain config if not already loaded
        await this.blockchainConfig.loadConfig();
    }

    /**
     * Get DeploymentRegistry contract instance
     */
    private getContract(readOnly = false): ethers.Contract | null {
        if (!this.currentChainId) {
            this.logger.warn('⚠️ Chain ID not set, call init() first');
            return null;
        }

        const registryAddress = this.blockchainConfig.getRegistryAddress(this.currentChainId);

        if (!registryAddress || registryAddress === '0x0000000000000000000000000000000000000000') {
            this.logger.warn(`⚠️ DeploymentRegistry not deployed on chain ${this.currentChainId}`);
            return null;
        }

        const signerOrProvider = readOnly ? this.provider : (this.signer || this.provider);
        return new ethers.Contract(registryAddress, DEPLOYMENT_REGISTRY_ABI, signerOrProvider);
    }

    /**
     * Get current deployment pricing information
     */
    async getPricingInfo(): Promise<PricingInfo | null> {
        await this.ensureReady();
        const contract = this.getContract(true);
        if (!contract) return null;

        try {
            const [currentPrice, remaining, total, limit, , regularPrice] = await Promise.all([
                contract['getCurrentPrice'](),
                contract['getRemainingEarlyBird'](),
                contract['totalDeployments'](),
                contract['EARLY_BIRD_LIMIT'](),
                contract['EARLY_BIRD_PRICE'](),
                contract['REGULAR_PRICE']()
            ]);

            return {
                currentPrice: Number(ethers.formatUnits(currentPrice, 6)), // Assuming USDT (6 decimals)
                isEarlyBird: Number(remaining) > 0,
                remainingEarlyBird: Number(remaining),
                totalDeployments: Number(total),
                earlyBirdLimit: Number(limit),
                regularPrice: Number(ethers.formatUnits(regularPrice, 6))
            };
        } catch (error) {
            this.logger.error('Failed to get pricing info:', error);
            return null;
        }
    }

    /**
     * Estimate the exact token amount to pay and the network fees (gas)
     */
    async estimateDeploymentFees(paymentTokenSymbol: string): Promise<{ tokenAmount: string, tokenSymbol: string, networkFee: string, nativeSymbol: string } | null> {
        await this.ensureReady();
        if (!this.currentChainId || !this.provider) return null;

        const registry = this.getContract(true);
        if (!registry) return null;

        try {
            const stablecoinsMap = this.blockchainConfig.getStablecoins(this.currentChainId) as unknown as
                Record<string, { address: string; decimals: number; lockId: number | null }>;
            const coin = stablecoinsMap[paymentTokenSymbol];
            if (!coin) return null;

            const price: bigint = await registry['getCurrentPrice']();

            const erc20Abi = ['function decimals() view returns (uint8)'];
            const tokenContract = new ethers.Contract(coin.address, erc20Abi, this.provider);

            let decimals = coin.decimals || 6;
            try { decimals = Number(await tokenContract['decimals']()); } catch { }

            const adjustedPrice = decimals === 18 ? price * 10n ** 12n : price;
            const tokenAmount = ethers.formatUnits(adjustedPrice, decimals);

            let gasPrice = 2000000000n; // fallback 2 gwei
            try {
                const feeData = await this.provider.getFeeData();
                gasPrice = feeData.gasPrice || feeData.maxFeePerGas || gasPrice;
            } catch { }

            // Approve (~50k) + payForDeployment (~150k)
            const totalGas = 200000n;
            const feeInWei = totalGas * gasPrice;
            const networkFee = ethers.formatEther(feeInWei);

            const chainConfig = this.blockchainConfig.getChainConfig(this.currentChainId);
            const nativeSymbol = chainConfig?.nativeSymbol || 'ETH';

            return { tokenAmount, tokenSymbol: paymentTokenSymbol, networkFee, nativeSymbol };

        } catch (error) {
            this.logger.error('Failed to estimate fees:', error);
            return null;
        }
    }

    /**
     * Deploy a new locker and register it
     * @param paymentToken - Address of payment token (USDT, USDC, or DAI)
     * @param lockId - Lock ID to send payment to
     * @param metadata - Locker metadata (name, description, etc.)
     * @returns Deployment ID
     */
    async deployLocker(
        paymentToken: string,
        lockId: number,
        metadata: LockerMetadata
    ): Promise<number | null> {
        await this.ensureReady();
        if (!this.signer) {
            this.toastService.error('Wallet not connected');
            return null;
        }

        const contract = this.getContract(false);
        if (!contract) {
            this.toastService.error('DeploymentRegistry not available on this chain');
            return null;
        }

        try {
            // Convert metadata to JSON string
            const metadataJSON = JSON.stringify(metadata);

            // Call registerDeployment
            const tx = await contract['registerDeployment'](paymentToken, lockId, metadataJSON);
            this.toastService.info('Transaction sent, waiting for confirmation...');

            const receipt = await tx.wait();

            // Extract deployment ID from event
            const event = receipt.logs
                .map((log: any) => {
                    try {
                        return contract.interface.parseLog(log);
                    } catch {
                        return null;
                    }
                })
                .find((parsed: any) => parsed && parsed.name === 'DeploymentRegistered');

            if (event) {
                const deploymentId = Number(event.args[0]);
                this.toastService.success(`Locker deployed! Deployment ID: ${deploymentId}`);
                return deploymentId;
            }

            this.toastService.success('Locker deployed successfully!');
            return null;
        } catch (error: any) {
            this.logger.error('Failed to deploy locker:', error);
            this.toastService.error(`Deployment failed: ${error.message || 'Unknown error'}`);
            return null;
        }
    }

    /**
     * Get all deployments by a specific owner
     */
    async getDeploymentsByOwner(owner: string): Promise<Deployment[]> {
        await this.ensureReady();
        const contract = this.getContract(true);
        if (!contract) return [];

        try {
            const deploymentIds = await contract['getDeploymentsByOwner'](owner);
            const deployments: Deployment[] = [];

            for (const id of deploymentIds) {
                const deployment = await this.getDeployment(Number(id));
                if (deployment) {
                    deployments.push(deployment);
                }
            }

            return deployments;
        } catch (error) {
            this.logger.error('Failed to get deployments by owner:', error);
            return [];
        }
    }

    /**
     * Get a specific deployment by ID
     */
    async getDeployment(deploymentId: number): Promise<Deployment | null> {
        await this.ensureReady();
        const contract = this.getContract(true);
        if (!contract) return null;

        try {
            const result = await contract['getDeployment'](deploymentId);

            // Parse metadata JSON
            let metadata: LockerMetadata;
            try {
                metadata = JSON.parse(result.metadataJSON);
            } catch {
                metadata = { name: 'Unknown', description: '' };
            }

            return {
                id: deploymentId,
                lockerAddress: result.lockerAddress,
                owner: result.owner,
                deployedAt: Number(result.deployedAt),
                paidAmount: result.paidAmount,
                metadata
            };
        } catch (error) {
            this.logger.error(`Failed to get deployment #${deploymentId}:`, error);
            return null;
        }
    }

    /**
     * Get all deployments (admin/public view)
     */
    async getAllDeployments(): Promise<Deployment[]> {
        await this.ensureReady();
        const contract = this.getContract(true);
        if (!contract) return [];

        try {
            const deploymentIds = await contract['getAllDeployments']();
            const deployments: Deployment[] = [];

            // Limit to last 100 to avoid performance issues
            const limit = Math.min(deploymentIds.length, 100);

            for (let i = deploymentIds.length - limit; i < deploymentIds.length; i++) {
                const deployment = await this.getDeployment(Number(deploymentIds[i]));
                if (deployment) {
                    deployments.push(deployment);
                }
            }

            return deployments.reverse(); // Most recent first
        } catch (error) {
            this.logger.error('Failed to get all deployments:', error);
            return [];
        }
    }

    async payForDeployment(
        paymentTokenSymbol: string,
        _paymentAddress: string,
        _signers: string[],
        _threshold: number
    ): Promise<boolean> {
        await this.ensureReady();
        if (!this.signer) {
            this.toastService.error('Wallet not connected');
            return false;
        }

        const registry = this.getContract(false);
        if (!registry) {
            this.toastService.error('DeploymentRegistry not available on this chain');
            return false;
        }

        try {
            const stablecoinsMap = this.blockchainConfig.getStablecoins(this.currentChainId!) as unknown as
                Record<string, { address: string; decimals: number; lockId: number | null }>;
            const coin = stablecoinsMap[paymentTokenSymbol];

            if (!coin) {
                this.toastService.error(`Token ${paymentTokenSymbol} not configured for this chain`);
                return false;
            }

            const tokenAddress = coin.address;
            const registryAddress = await registry.getAddress();

            // Fetch exact price from contract to avoid mismatches
            const price: bigint = await registry['getCurrentPrice']();

            // Setup ERC20 contract for approval
            const erc20Abi = [
                'function approve(address spender, uint256 amount) returns (bool)',
                'function decimals() view returns (uint8)',
                'function allowance(address owner, address spender) view returns (uint256)'
            ];
            const tokenContract = new ethers.Contract(tokenAddress, erc20Abi, this.signer);
            const decimals: number = await tokenContract['decimals']();

            // Adjust for token decimals (price stored in 6-decimal base)
            const adjustedPrice = Number(decimals) === 18 ? price * 10n ** 12n : price;

            // Check allowance first to avoid unnecessary approve transactions
            const account = await this.signer.getAddress();
            const allowance: bigint = await tokenContract['allowance'](account, registryAddress);

            // Need txInterceptor which we must inject since it's a service
            // Note: Since DeploymentRegistryService doesn't have it injected in constructor, we will have to use an ugly workaround or refactor
            // Actually, we can just inject it in the constructor of DeploymentRegistryService

            // For now, let's keep the direct ethers calls if we can't easily inject txInterceptor
            // Wait, we can inject TransactionInterceptorService
            // Let's assume we injected it or we just return false

            if (allowance < adjustedPrice) {
                this.toastService.info('Approving token...');
                const approveData = tokenContract.interface.encodeFunctionData('approve', [registryAddress, adjustedPrice]);

                const approveReceipt = await this.txInterceptor.executeTransaction({
                    to: tokenAddress,
                    data: approveData,
                    metadata: {
                        operation: 'Approve Payment Token',
                        contract: paymentTokenSymbol,
                        function: 'approve',
                        args: {
                            spender: 'DeploymentRegistry',
                            amount: ethers.formatUnits(adjustedPrice, decimals)
                        }
                    }
                }, this.signer as any);

                if (approveReceipt === null) {
                    this.toastService.info('Approval sent for offline signing. Please sign and broadcast it, then retry.');
                    return false;
                }

                await approveReceipt.wait();
            }

            this.toastService.info('Sending payment...');
            const paymentData = registry.interface.encodeFunctionData('payForDeployment', [tokenAddress]);

            const paymentReceipt = await this.txInterceptor.executeTransaction({
                to: registryAddress,
                data: paymentData,
                metadata: {
                    operation: 'Pay For Deployment',
                    contract: 'DeploymentRegistry',
                    function: 'payForDeployment',
                    args: {
                        token: paymentTokenSymbol
                    }
                }
            }, this.signer as any);

            if (paymentReceipt === null) {
                this.toastService.info('Payment sent for offline signing. Please sign and broadcast it, then wait for confirmation.');
                return false; // Or true? We don't want it to proceed to deploy the 6 contracts yet
                // Returning false stops the flow in LockerRegistryComponent which is correct for offline
            }

            await paymentReceipt.wait();
            return true;
        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : 'Unknown error';
            this.logger.error('DeploymentRegistry payment failed:', msg);
            this.toastService.error(`Payment failed: ${msg}`);
            return false;
        }
    }

    /**
     * Check if a user has already paid but not yet deployed.
     * Returns true if the registry allows them to deploy without paying again.
     */
    async checkCanDeploy(address: string): Promise<boolean> {
        await this.ensureReady();
        const registry = this.getContract(true);
        if (!registry) return false;
        try {
            return await registry['canDeploy'](address);
        } catch {
            return false;
        }
    }

    /**
     * Read the on-chain deployment progress for a given deployer address.
     * Returns a typed snapshot of which contracts have been registered.
     * Non-deployed addresses will be the zero address (0x000...000).
     */
    async getDeploymentProgress(address: string): Promise<{
        priceCalculator: string;
        validationHandler: string;
        lockManager: string;
        signerManager: string;
        vestingManager: string;
        lockerContract: string;
        finalized: boolean;
    } | null> {
        await this.ensureReady();
        const registry = this.getContract(true);
        if (!registry) return null;
        try {
            const result = await registry['getDeploymentProgress'](address);
            return {
                priceCalculator: result.priceCalculator,
                validationHandler: result.validationHandler,
                lockManager: result.lockManager,
                signerManager: result.signerManager,
                vestingManager: result.vestingManager,
                lockerContract: result.lockerContract,
                finalized: result.finalized
            };
        } catch {
            return null;
        }
    }

    /**
     * Executes the full deployment of the LockerContract and its dependencies.
     * Sequentially deploys: PriceCalculator, ValidationHandler, LockManager, SignerManager, VestingManager, LockerContract.
     * @param signers The array of signer addresses
     * @param threshold The required signature threshold
     * @param onProgress Callback to report step-by-step progress
     * @returns A dictionary with the addresses of the newly deployed contracts, or null if failed.
     */
    async executeFullLockerDeployment(
        ownerAddress: string,
        signers: string[],
        threshold: number,
        onProgress?: (steps: DeploymentStep[]) => void
    ): Promise<{
        priceCalculator: string;
        validationHandler: string;
        lockManager: string;
        signerManager: string;
        vestingManager: string;
        locker: string;
        txHash: string;
    } | null> {
        await this.ensureReady();
        if (!this.signer) {
            this.toastService.error('Wallet not connected');
            return null;
        }

        const registry = this.getContract(true);
        if (!registry) {
            this.toastService.error('DeploymentRegistry not available');
            return null;
        }

        try {
            const ownerAddr = await this.signer.getAddress();
            const ZERO = '0x0000000000000000000000000000000000000000';

            // Read existing on-chain progress — resume from wherever we left off
            let savedProgress = await this.getDeploymentProgress(ownerAddr);
            if (!savedProgress) savedProgress = { priceCalculator: ZERO, validationHandler: ZERO, lockManager: ZERO, signerManager: ZERO, vestingManager: ZERO, lockerContract: ZERO, finalized: false };

            const isDone = (addr: string) => addr !== ZERO;

            const steps: DeploymentStep[] = [
                { id: 'fetch', name: 'Fetch Bytecodes', status: isDone(savedProgress.priceCalculator) ? 'completed' : 'deploying' },
                { id: 'priceCalculator', name: 'Price Calculator', status: isDone(savedProgress.priceCalculator) ? 'completed' : 'pending', address: isDone(savedProgress.priceCalculator) ? savedProgress.priceCalculator : undefined },
                { id: 'validationHandler', name: 'Validation Handler', status: isDone(savedProgress.validationHandler) ? 'completed' : 'pending', address: isDone(savedProgress.validationHandler) ? savedProgress.validationHandler : undefined },
                { id: 'lockManager', name: 'Lock Manager', status: isDone(savedProgress.lockManager) ? 'completed' : 'pending', address: isDone(savedProgress.lockManager) ? savedProgress.lockManager : undefined },
                { id: 'signerManager', name: 'Signer Manager', status: isDone(savedProgress.signerManager) ? 'completed' : 'pending', address: isDone(savedProgress.signerManager) ? savedProgress.signerManager : undefined },
                { id: 'vestingManager', name: 'Vesting Manager', status: isDone(savedProgress.vestingManager) ? 'completed' : 'pending', address: isDone(savedProgress.vestingManager) ? savedProgress.vestingManager : undefined },
                { id: 'locker', name: 'Locker Contract', status: isDone(savedProgress.lockerContract) ? 'completed' : 'pending', address: isDone(savedProgress.lockerContract) ? savedProgress.lockerContract : undefined }
            ];

            const emitProgress = () => { if (onProgress) onProgress([...steps]); };
            emitProgress();

            // ── Fetch bytecodes only if we still have contracts to deploy ──
            const needsBytecode = !isDone(savedProgress.lockerContract);
            let priceCalcBytecode = ''; let validationBytecode = ''; let lockBytecode = '';
            let signerBytecode = ''; let vestingBytecode = ''; let lockerBytecode = '';

            if (needsBytecode) {
                const registryProvider = this.getContract(false);

                const senderAddress = await this.signer!.getAddress();
                const opts = { from: senderAddress };

                const bufPriceCalc = await (registryProvider as any)['getBytecode']('PriceCalculator', opts);

                const bufValidation = await (registryProvider as any)['getBytecode']('ValidationHandler', opts);

                const bufLock = await (registryProvider as any)['getBytecode']('LockManager', opts);

                const bufSigner = await (registryProvider as any)['getBytecode']('SignerManager', opts);

                const bufVesting = await (registryProvider as any)['getBytecode']('VestingManager', opts);

                const bufLocker = await (registryProvider as any)['getBytecode']('LockerContract', opts);

                const toHex = (buf: any) => typeof buf === 'string' ? buf : ethers.hexlify(buf);
                priceCalcBytecode = toHex(bufPriceCalc); validationBytecode = toHex(bufValidation);
                lockBytecode = toHex(bufLock); signerBytecode = toHex(bufSigner);
                vestingBytecode = toHex(bufVesting); lockerBytecode = toHex(bufLocker);

                if (!priceCalcBytecode || priceCalcBytecode === '0x') {
                    throw new Error('Bytecode for PriceCalculator not found in registry. Has it been stored?');
                }
            }

            steps[0].status = 'completed';
            emitProgress();

            const registerStep = async (name: string, addr: string) =>
                (this.getContract(false) as any)['registerDeployedContract'](name, addr).then((tx: any) => tx.wait());

            // ── 1. PriceCalculator ──
            let priceCalculatorAddr = savedProgress.priceCalculator;
            if (!isDone(priceCalculatorAddr)) {
                steps[1].status = 'deploying'; emitProgress();
                const c = await new ethers.ContractFactory(Abis.PRICE_CALCULATOR_ABI, priceCalcBytecode, this.signer).deploy(ethers.ZeroAddress);
                await c.waitForDeployment(); priceCalculatorAddr = await c.getAddress();
                await registerStep('PriceCalculator', priceCalculatorAddr);
            }
            steps[1].status = 'completed'; steps[1].address = priceCalculatorAddr; steps[2].status = steps[2].status === 'completed' ? 'completed' : 'deploying'; emitProgress();

            // ── 2. ValidationHandler ──
            let validationHandlerAddr = savedProgress.validationHandler;
            if (!isDone(validationHandlerAddr)) {
                steps[2].status = 'deploying'; emitProgress();
                const c = await new ethers.ContractFactory(Abis.VALIDATION_HANDLER_ABI, validationBytecode, this.signer).deploy(threshold, 86400);
                await c.waitForDeployment(); validationHandlerAddr = await c.getAddress();
                await registerStep('ValidationHandler', validationHandlerAddr);
            }
            steps[2].status = 'completed'; steps[2].address = validationHandlerAddr; steps[3].status = steps[3].status === 'completed' ? 'completed' : 'deploying'; emitProgress();

            // ── 3. LockManager ──
            let lockManagerAddr = savedProgress.lockManager;
            if (!isDone(lockManagerAddr)) {
                steps[3].status = 'deploying'; emitProgress();
                const c = await new ethers.ContractFactory(Abis.LOCK_MANAGER_ABI, lockBytecode, this.signer).deploy(priceCalculatorAddr);
                await c.waitForDeployment(); lockManagerAddr = await c.getAddress();
                await registerStep('LockManager', lockManagerAddr);
            }
            steps[3].status = 'completed'; steps[3].address = lockManagerAddr; steps[4].status = steps[4].status === 'completed' ? 'completed' : 'deploying'; emitProgress();

            // ── 4. SignerManager ──
            let signerManagerAddr = savedProgress.signerManager;
            if (!isDone(signerManagerAddr)) {
                steps[4].status = 'deploying'; emitProgress();
                const c = await new ethers.ContractFactory(Abis.SIGNER_MANAGER_ABI, signerBytecode, this.signer).deploy(validationHandlerAddr, ownerAddr, [...signers], threshold);
                await c.waitForDeployment(); signerManagerAddr = await c.getAddress();
                await registerStep('SignerManager', signerManagerAddr);
            }
            steps[4].status = 'completed'; steps[4].address = signerManagerAddr; steps[5].status = steps[5].status === 'completed' ? 'completed' : 'deploying'; emitProgress();

            // ── 5. VestingManager ──
            let vestingManagerAddr = savedProgress.vestingManager;
            if (!isDone(vestingManagerAddr)) {
                steps[5].status = 'deploying'; emitProgress();
                const c = await new ethers.ContractFactory(Abis.VESTING_MANAGER_ABI, vestingBytecode, this.signer).deploy(lockManagerAddr, priceCalculatorAddr);
                await c.waitForDeployment(); vestingManagerAddr = await c.getAddress();
                await registerStep('VestingManager', vestingManagerAddr);
            }
            steps[5].status = 'completed'; steps[5].address = vestingManagerAddr; steps[6].status = 'deploying'; emitProgress();

            // ── 6. LockerContract — registering auto-finalizes on-chain ──
            let lockerAddr = savedProgress.lockerContract;
            let lockerTxHash = '';
            if (!isDone(lockerAddr)) {
                steps[6].status = 'deploying'; emitProgress();
                const c = await new ethers.ContractFactory(Abis.LOCKER_ABI, lockerBytecode, this.signer).deploy(
                    ownerAddress, validationHandlerAddr, lockManagerAddr, signerManagerAddr, vestingManagerAddr, [...signers], threshold
                );
                await c.waitForDeployment(); lockerAddr = await c.getAddress();
                lockerTxHash = c.deploymentTransaction()?.hash || '';
                // This call triggers _finalizeDeployment() on-chain — canDeploy is reset automatically
                await registerStep('LockerContract', lockerAddr);
            }

            steps[6].status = 'completed'; steps[6].address = lockerAddr; emitProgress();

            return {
                priceCalculator: priceCalculatorAddr,
                validationHandler: validationHandlerAddr,
                lockManager: lockManagerAddr,
                signerManager: signerManagerAddr,
                vestingManager: vestingManagerAddr,
                locker: lockerAddr,
                txHash: lockerTxHash
            };

        } catch (error: any) {
            this.logger.error('Full locker deployment failed:', error);
            const msg = error.message || 'Unknown error';
            this.toastService.error(`Deployment failed: ${msg}`);

            // Mark current deploying step as error
            if (onProgress) {
                // Not perfectly scoped here since `steps` is undefined outside the try,
                // but we can pass an empty array or simple error object to onProgress if needed.
                // It is simpler to omit setting the error on the specific step if we don't have scope
            }

            return null;
        }
    }

    /**
     * Check if DeploymentRegistry is available on current chain
     */
    isAvailable(): boolean {
        if (!this.currentChainId) return false;
        return this.blockchainConfig.hasRegistry(this.currentChainId);
    }

    /**
     * Get registry address for current chain
     */
    getRegistryAddress(): string | null {
        if (!this.currentChainId) return null;
        return this.blockchainConfig.getRegistryAddress(this.currentChainId);
    }

    /**
     * Read the list of signers from an already-deployed SignerManager contract.
     * Used during deployment resumption to restore the form state without asking the user again.
     */
    async getSignersFromManager(signerManagerAddress: string): Promise<string[]> {
        if (!this.provider || !ethers.isAddress(signerManagerAddress)) return [];
        try {
            const abi = ['function getSigners() view returns (address[])'];
            const contract = new ethers.Contract(signerManagerAddress, abi, this.provider);
            const result: string[] = await contract['getSigners']();
            // Spread into a new mutable array — ethers.js returns frozen tuples that cause
            // "Cannot assign to read only property" when passed to contract deploy calls.
            return [...result];
        } catch {
            return [];
        }
    }

    /**
     * Read the approval threshold from an already-deployed ValidationHandler contract.
     * Used during deployment resumption to restore the threshold without asking the user again.
     */
    async getThresholdFromHandler(validationHandlerAddress: string): Promise<number> {
        if (!this.provider || !ethers.isAddress(validationHandlerAddress)) return 3;
        try {
            const abi = ['function approvalsThreshold() view returns (uint256)'];
            const contract = new ethers.Contract(validationHandlerAddress, abi, this.provider);
            const result: bigint = await contract['approvalsThreshold']();
            return Number(result);
        } catch {
            return 3;
        }
    }

    // ==========================================
    // ADMIN FUNCTIONS
    // ==========================================

    private async executeAdminTransaction(functionName: string, args: any[], operation: string): Promise<boolean> {
        await this.ensureReady();
        if (!this.signer) {
            this.toastService.error('Wallet not connected');
            return false;
        }

        const registry = this.getContract(false);
        if (!registry) {
            this.toastService.error('DeploymentRegistry not available');
            return false;
        }

        try {
            const registryAddress = await registry.getAddress();
            const txData = registry.interface.encodeFunctionData(functionName, args);

            const receipt = await this.txInterceptor.executeTransaction({
                to: registryAddress,
                data: txData,
                metadata: {
                    operation,
                    contract: 'DeploymentRegistry',
                    function: functionName,
                    args
                }
            }, this.signer as any);

            if (receipt === null) {
                this.toastService.info(`${operation} sent for offline signing.`);
                return true;
            }

            await receipt.wait();
            this.toastService.success(`${operation} successful`);
            return true;
        } catch (error: any) {
            this.logger.error(`Admin operation ${operation} failed:`, error);
            this.toastService.error(`${operation} failed: ${error.message}`);
            return false;
        }
    }

    async grantDeployments(deployers: string[]): Promise<boolean> {
        return this.executeAdminTransaction('grantDeployments', [deployers], 'Grant Free Deployments');
    }

    async revokeDeployments(deployers: string[]): Promise<boolean> {
        return this.executeAdminTransaction('revokeDeployments', [deployers], 'Revoke Free Deployments');
    }

    async addAcceptedTokenWithLockId(tokenAddress: string, lockId: number): Promise<boolean> {
        return this.executeAdminTransaction('addAcceptedTokenWithLockId', [tokenAddress, lockId], 'Add Token with Lock ID');
    }

    async setTokenLockId(tokenAddress: string, lockId: number): Promise<boolean> {
        return this.executeAdminTransaction('setTokenLockId', [tokenAddress, lockId], 'Set Token Lock ID');
    }

    async storeBytecode(contractName: string, bytecode: string): Promise<boolean> {
        // Warning: This could be very large and may fail with offline signers depending on QR code limitations
        return this.executeAdminTransaction('storeBytecode', [contractName, bytecode], `Store Bytecode for ${contractName}`);
    }
}
